// The dock controls' accessible contract: DockControl's pressed and disabled states, the
// background pause toggle, and no native title over a Tooltip.

import { mount } from "@vue/test-utils";
import { describe, expect, it, vi } from "vitest";
import DockControl from "@glass/components/dock/DockControl.vue";
import { nextTick, ref, watch } from "vue";
import DockBackgroundToggle from "@glass/components/dock/DockBackgroundToggle.vue";
import { read } from "../../../../tests/harness/source";

// ══ DockControl — aria-pressed tri-state and the focusable disabled boundary ═══════════════
// DockControl selectable/disabled a11y contract (W1-B aria-pressed tri-state +
// W5-C boundary-disabled-stays-focusable). Both cut the ONE `stateAttrs` seat.
//
// This asserts the RENDERED contract — a stale `stateAttrs` binding that silently
// no-ops is caught only by a rendered-attr assertion (the binding-verification
// discipline).
//
// W1-B bite (tri-state): `active` is a THREE-state discriminant — unset ⇒ nav mode
// (NO aria-pressed), `false` ⇒ off-state toggle (aria-pressed="false"), `true` ⇒
// on (aria-pressed="true"). The naive both-states stamp reddens the nav-mode guard;
// the HEAD "only-when-truthy" stamp reddens the off-state announce.
// W5-C bite (focusable-disabled): a disabled button arm keeps `aria-disabled` +
// activation-suppression but drops the NATIVE `disabled` stamp, so a boundary nav
// control stays focusable (PRESENT-but-disabled), never DOM-unreachable.

const slots = { default: () => "icon" };

describe("DockControl — aria-pressed tri-state (W1-B)", () => {
    it("omits aria-pressed entirely in nav mode (active unset)", () => {
        const w = mount(DockControl, { slots });
        expect(w.get("button").attributes("aria-pressed")).toBeUndefined();
    });

    it("announces aria-pressed=\"false\" for an off-state toggle (active: false)", () => {
        const w = mount(DockControl, { props: { active: false }, slots });
        expect(w.get("button").attributes("aria-pressed")).toBe("false");
    });

    it("announces aria-pressed=\"true\" for an on-state toggle (active: true)", () => {
        const w = mount(DockControl, { props: { active: true }, slots });
        expect(w.get("button").attributes("aria-pressed")).toBe("true");
    });

    it("keeps data-active + glass-capsule truthy-gated (present only when on)", () => {
        const on = mount(DockControl, { props: { active: true }, slots });
        const off = mount(DockControl, { props: { active: false }, slots });
        const nav = mount(DockControl, { slots });
        expect(on.get("button").attributes("data-active")).toBe("");
        expect(on.get("button").classes()).toContain("glass-capsule");
        expect(off.get("button").attributes("data-active")).toBeUndefined();
        expect(off.get("button").classes()).not.toContain("glass-capsule");
        expect(nav.get("button").attributes("data-active")).toBeUndefined();
    });
});

describe("DockControl — boundary-disabled stays focusable (W5-C)", () => {
    it("drops the native disabled stamp on the button arm (stays focusable)", () => {
        const w = mount(DockControl, { props: { disabled: true }, slots });
        const btn = w.get("button");
        expect(btn.attributes("disabled")).toBeUndefined();
        expect(btn.attributes("aria-disabled")).toBe("true");
    });

    it("suppresses activation while disabled (no click through)", async () => {
        const onClick = vi.fn();
        const w = mount(DockControl, {
            props: { disabled: true, onClick },
            slots,
        });
        await w.get("button").trigger("click");
        expect(onClick).not.toHaveBeenCalled();
    });

    it("activates normally when enabled", async () => {
        const onClick = vi.fn();
        const w = mount(DockControl, { props: { onClick }, slots });
        await w.get("button").trigger("click");
        expect(onClick).toHaveBeenCalledTimes(1);
    });
});

// ══ DockBackgroundToggle — WCAG 2.2.2 pause/play ═══════════════════════════════════════════
// The WCAG 2.2.2 (Pause, Stop, Hide), Level-A pause/play toggle for
// the backgrounds. The control is available to ALL users (NOT gated behind
// reduced-motion), binds an EXISTING renderer seam (pause()/resume()), and
// reflects state via aria-pressed + a Pause↔Play glyph swap.
//
// This asserts the RENDERED a11y contract — NOT just mount success — per the
// glass-ui-binding-verification discipline (a stale aria binding silently
// no-ops; only a rendered-attr assertion catches it).
//
// Bite: drop aria-pressed (or stop swapping the glyph) → the contract reddens.

describe("DockBackgroundToggle — WCAG 2.2.2 pause/play (G2)", () => {
    it("reflects paused via aria-pressed and swaps the glyph + label", async () => {
        const wrapper = mount(DockBackgroundToggle, { props: { paused: false } });
        const btn = wrapper.get("button");

        // RUNNING: not pressed, the Pause action label, the Pause glyph.
        expect(btn.attributes("aria-pressed")).toBe("false");
        expect(btn.attributes("aria-label")).toBe("Pause background animation");
        // Lucide renders an <svg>; the Pause icon has two vertical bars (rects).
        expect(wrapper.findAll("svg").length).toBe(1);

        // PAUSED: pressed, the Play (resume) action label.
        await wrapper.setProps({ paused: true });
        expect(btn.attributes("aria-pressed")).toBe("true");
        expect(btn.attributes("aria-label")).toBe("Resume background animation");
        expect(wrapper.findAll("svg").length).toBe(1);
    });

    it("emits update:paused on click (the v-model toggle)", async () => {
        const wrapper = mount(DockBackgroundToggle, { props: { paused: false } });
        await wrapper.get("button").trigger("click");
        expect(wrapper.emitted("update:paused")?.[0]).toEqual([true]);

        await wrapper.setProps({ paused: true });
        await wrapper.get("button").trigger("click");
        expect(wrapper.emitted("update:paused")?.[1]).toEqual([false]);
    });

    it("drives a bound renderer pause()/resume() via the v-model seam", async () => {
        // The canonical consumer wiring: a paused ref bound to the toggle, with a
        // watcher routing it to the renderer's existing pause()/resume().
        const renderer = { pause: vi.fn(), resume: vi.fn() };
        const paused = ref(false);
        watch(paused, (p) => (p ? renderer.pause() : renderer.resume()));

        const wrapper = mount(DockBackgroundToggle, {
            props: {
                paused: paused.value,
                "onUpdate:paused": (v: boolean) => (paused.value = v),
            },
        });

        await wrapper.get("button").trigger("click");
        await nextTick();
        expect(paused.value).toBe(true);
        expect(renderer.pause).toHaveBeenCalledTimes(1);
        expect(renderer.resume).not.toHaveBeenCalled();
    });

    it("honors custom labels", async () => {
        const wrapper = mount(DockBackgroundToggle, {
            props: { paused: false, pauseLabel: "Halt drift", playLabel: "Run drift" },
        });
        expect(wrapper.get("button").attributes("aria-label")).toBe("Halt drift");
        await wrapper.setProps({ paused: true });
        expect(wrapper.get("button").attributes("aria-label")).toBe("Run drift");
    });
});

// ══ O-8 — no native title on a control that carries a Tooltip ══════════════════════════════
// BK row #31 (W-A11Y) — O-8: "the native `title` tooltip occludes the control it
// describes" (COMPONENT-WAVES-TERMINAL D-6; the capture shows a raw dark
// square-cornered rect covering the trigger it labels — the browser's tooltip, not
// ours). The routed cure, verbatim: "strike `title` from any control that carries a
// `<Tooltip>`."
//
// The two sites, both in the dock family, whose documented label affordance IS the
// library's `<Tooltip side="right">` (recorded at
// `dock/styles/controls/touch-floor.css`):
//   · `DockLayerGroup.vue` switcher tabs — the switcher story wraps every entry in a Tooltip;
//   · `DockBackgroundToggle.vue` — `demo/shell/SidebarDock.vue` wraps the whole dock
//     control set in one.
// Both carried `:title` AND `:aria-label`, so the native rect painted over the styled
// one on the browser's own delay, and the browser's delay is not ours to tune.
//
// RENDERED-attr asserts: an attribute that survives in the template but is dropped by
// `inheritAttrs`/`v-bind` plumbing (or the reverse) is caught only in the rendered DOM
// — the binding-verification discipline.

describe("O-8 — a control that carries a <Tooltip> renders no native title", () => {
    it("DockBackgroundToggle renders aria-label and NO title", () => {
        const wrapper = mount(DockBackgroundToggle, {
            props: { paused: false, pauseLabel: "Pause background" },
        });
        const control = wrapper.find("button");
        expect(control.exists()).toBe(true);
        expect(control.attributes("aria-label")).toBe("Pause background");
        expect(
            control.attributes("title"),
            "the accessible name is aria-label; title only added a second, unstyled tooltip",
        ).toBeUndefined();
    });

    it("the switcher tab template stamps no title either", () => {
        // Rendering the switcher needs the whole dock layer context; the assertion that
        // matters is that the attribute is not authored, and the sibling site above
        // proves the rendered form of the same strike.
        const template = read("src/components/dock/DockLayerGroup.vue").replace(
            /<!--[\s\S]*?-->/g,
            "",
        );
        expect(template).not.toMatch(/:title=/);
    });

    it("the strike is family-wide — no dock control re-introduces one", () => {
        // O-8 is a CLASS, not two sites: the next dock control to want a label must
        // reach for the Tooltip the family already ships.
        const offenders: string[] = [];
        for (const file of [
            "src/components/dock/DockControl.vue",
            "src/components/dock/DockLayerGroup.vue",
            "src/components/dock/DockLayer.vue",
            "src/components/dock/DockBackgroundToggle.vue",
            "src/components/dock/GlassDock.vue",
        ]) {
            const template = read(file).replace(/<!--[\s\S]*?-->/g, "");
            if (/\s:?title="/.test(template)) offenders.push(file);
        }
        expect(offenders).toEqual([]);
    });
});
